Here is a robust pattern for achieving this in a userscript.

### Key Considerations for Userscripts
1.  **Same-Origin Policy**: The iframe must load a URL from the **same domain** as the page where your script runs. If the account page is on a different subdomain or domain, the iframe will be blocked from accessing the DOM due to browser security restrictions.
2.  **Invisibility**: We can hide the iframe using CSS (`display: none` or `visibility: hidden`), or simply position it off-screen.
3.  **Asynchronous Flow**: Since loading an iframe is asynchronous, you must use a `Promise` or `async/await` to ensure the data is saved before the next function runs.

### Implementation Example

This example assumes your account page is on the same domain (e.g., `example.com/account`).

```javascript
// ==UserScript==
// @name         Invisible Iframe User ID Fetcher
// @match        https://example.com/*
// @namespace    http://tampermonkey.net/
// @version      1.0
// @grant        GM_xmlhttpRequest // Optional, if you need to bypass some sandboxing, but standard fetch works here
// @grant        GM_setValue      // Recommended for userscripts over localStorage for security
// @run-at       document-idle
// ==/UserScript==

(function() {
    'use strict';

    // Configuration
    const ACCOUNT_URL = 'https://example.com/account'; // Must be same origin as the script
    const STORAGE_KEY = 'user_id_cache';

    /**
     * Function to load the iframe, extract the ID, and return a Promise.
     */
    async function fetchUserIdFromIframe() {
        return new Promise((resolve, reject) => {
            const iframe = document.createElement('iframe');

            // 1. Hide the iframe
            iframe.style.display = 'none';
            iframe.style.visibility = 'hidden';
            // Optional: Position off-screen
            iframe.style.position = 'absolute';
            iframe.style.top = '-9999px';

            // 2. Set the source
            iframe.src = ACCOUNT_URL;

            // 3. Handle load event (use 'load' instead of 'DOMContentLoaded' to ensure script execution)
            iframe.onload = () => {
                try {
                    const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;

                    // --- MODIFY THIS SELECTOR ---
                    // Target the element containing the user ID. 
                    // Replace '#user-id' with the actual ID or class selector on the account page.
                    const userIdElement = iframeDoc.querySelector('#user-id'); 

                    if (userIdElement) {
                        const userId = userIdElement.innerText.trim();

                        if (userId) {
                            // 4. Save to storage
                            // Using GM_setValue is preferred in userscripts, but localStorage works too:
                            localStorage.setItem(STORAGE_KEY, userId);

                            // Cleanup: Remove iframe from DOM
                            document.body.removeChild(iframe);

                            resolve(userId);
                        } else {
                            reject(new Error('User ID element found but is empty.'));
                        }
                    } else {
                        reject(new Error('User ID element not found in iframe.'));
                    }
                } catch (err) {
                    // If Same-Origin Policy blocks access
                    console.error('Cross-Origin Error:', err);
                    reject(new Error('Cannot access iframe content due to Same-Origin Policy. Ensure URLs match.'));

                    // Cleanup even if failed
                    if (iframe.parentNode) {
                        document.body.removeChild(iframe);
                    }
                }
            };

            iframe.onerror = (e) => {
                reject(new Error('Failed to load iframe content: ' + e));
                if (iframe.parentNode) document.body.removeChild(iframe);
            };

            // Append to body so the browser loads it
            document.body.appendChild(iframe);
        });
    }

    /**
     * The main execution chain
     */
    async function main() {
        try {
            console.log('Starting iframe fetch...');

            // 1. Fetch and Save
            const userId = await fetchUserIdFromIframe();
            console.log(`User ID fetched and saved: ${userId}`);

            // 2. Pass to next function
            processUserId(userId);

        } catch (error) {
            console.error('Failed to fetch user ID:', error);
            // Fallback or error handling
            console.warn('Using fallback or stopping execution.');
        }
    }

    /**
     * The next function in the chain
     */
    function processUserId(userId) {
        console.log('Processing ID:', userId);
        // Perform your subsequent logic here
        // Example: Update UI, make API calls, etc.
    }

    // Run immediately when script loads
    main();

})();
```

### Important Troubleshooting Notes

1.  **Same-Origin Policy (CORS)**:
    If the `ACCOUNT_URL` is on a different domain (e.g., `example.com` vs `api.example.com`), `iframe.contentDocument` will throw a security error. You cannot read the content of an iframe from a different origin.
    *   **Solution**: If the account page is on a different domain, you must use `GM_xmlhttpRequest` to fetch the HTML of the account page as a string, parse it in your script, and extract the ID.

2.  **Selector Reliability**:
    The line `iframeDoc.querySelector('#user-id')` relies on the account page having a specific HTML element. If the account page uses dynamic JavaScript to load the user ID *after* the initial load, the `onload` event might fire too early.
    *   **Solution**: If the content is dynamic, you may need to add a `MutationObserver` inside the `onload` handler to wait for the specific element to appear.

3.  **Storage Priority**:
    While `localStorage` works, Tampermonkey and similar managers provide `GM_setValue` and `GM_getValue`. These are generally safer (they don't share data with the page's JavaScript) and persist across browser restarts even if the user clears site data.
    *   *Code change*: Replace `localStorage.setItem` with `GM_setValue(STORAGE_KEY, userId);`.
